INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Qubit immer entweder 0 oder 1?', 2, '[{"text": "Nein", "correct": true, "because": "Qubits können in Superposition sein"}, {"text": "Ja", "correct": false, "because": "Ignoriert quantenmechanische Zustände"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip nutze ich, um mehrere Zustände gleichzeitig zu berechnen?', 3, '[{"text": "Superposition", "correct": true, "because": "Erlaubt parallele Zustände"}, {"text": "Binäre Logik", "correct": false, "because": "Nur klassische Computer"}, {"text": "Caching", "correct": false, "because": "Speicheroptimierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen Qubits für bestimmte Berechnungen effektiv?', 4, '[{"text": "Superposition", "correct": true, "because": "Mehrere Zustände gleichzeitig"}, {"text": "Verschränkung", "correct": true, "because": "Korrelierte Zustände"}, {"text": "Hohe Taktfrequenz", "correct": false, "because": "Klassische CPUs"}, {"text": "Großer Speicher", "correct": false, "because": "Nicht primär relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Qubits sind fehleranfälliger als Bits. b) Quantenalgorithmen sind immer schneller.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) hängt vom Algorithmus ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht universell"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Entwicklung eines Quantenprozessors?', 4, '[{"text": "Fehlerkorrektur", "correct": false, "because": "Entscheidend für Stabilität"}, {"text": "Kühlung", "correct": false, "because": "Notwendig für Qubit-Kohärenz"}, {"text": "Betriebssystem", "correct": true, "because": "Nicht primär für Hardware"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Verschränkung die Rechenleistung direkt erhöht?', 3, '[{"text": "Nein", "correct": true, "because": "Sie ermöglicht Korrelationen, nicht direkt Leistung"}, {"text": "Ja", "correct": false, "because": "Verwechselt mit Superposition"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Problem löst der Shor-Algorithmus effizient ?', 4, '[{"text": "Faktorisierung großer Zahlen", "correct": true, "because": "Bricht Kryptosysteme"}, {"text": "Datenbank-Suche", "correct": false, "because": "Das ist Grover"}, {"text": "Sortierung", "correct": false, "because": "Klassische Algorithmen besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren sind für einen stabilen Quantenprozessor entscheidend?', 5, '[{"text": "Niedrige Fehlerquote", "correct": true, "because": "Minimiert Rechenfehler"}, {"text": "Lange Kohärenzzeit", "correct": true, "because": "Hält Zustände stabil"}, {"text": "Hohe Taktfrequenz", "correct": false, "because": "Klassische CPUs"}, {"text": "Großer Cache", "correct": false, "because": "Irrelevant für Qubits"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Quantenprozessoren brauchen extreme Kälte. b) Sie ersetzen klassische CPUs. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, sie ergänzen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Quantenberechnung?', 3, '[{"text": "Qubits", "correct": false, "because": "Grundlage der Berechnung"}, {"text": "Quantenalgorithmen", "correct": false, "because": "Steuern die Logik"}, {"text": "Grafikkarte", "correct": true, "because": "Für klassische Systeme"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Quantenprozessoren für alle Aufgaben besser?', 2, '[{"text": "Nein", "correct": true, "because": "Nur spezifische Probleme vorteilhaft"}, {"text": "Ja", "correct": false, "because": "Nicht universell überlegen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien werden oft für Qubits genutzt?', 4, '[{"text": "Supraleitende Schaltkreise", "correct": true, "because": "Niedrige Temperaturen"}, {"text": "Ionenfallen", "correct": true, "because": "Präzise Zustandskontrolle"}, {"text": "Mechanische Relais", "correct": false, "because": "Veraltete Technik"}, {"text": "Optische Sensoren", "correct": false, "because": "Nicht primär für Qubits"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Quantenprozessoren Kryptografie sofort knacken. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Nur mit ausreichend Qubits möglich"}, {"text": "Ja", "correct": false, "because": "Technologie noch nicht ausgereift"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Optimierung eines Quantenalgorithmus?', 4, '[{"text": "Minimierung der Gatteranzahl", "correct": true, "because": "Reduziert Fehler"}, {"text": "Maximale Speicherkapazität", "correct": false, "because": "Nicht primär relevant"}, {"text": "Hohe Parallelität", "correct": false, "because": "Schon durch Superposition gegeben"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Grover-Algorithmus optimiert Suchen. b) Quantenprozessoren sind wartungsfrei.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, sie sind komplex"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Quantenprozessoren für Simulationen?', 5, '[{"text": "Schnelle Molekülsimulation", "correct": true, "because": "Nutzt Superposition"}, {"text": "Effiziente Optimierung", "correct": true, "because": "Parallele Zustände"}, {"text": "Einfache Programmierung", "correct": false, "because": "Sehr komplex"}, {"text": "Geringer Stromverbrauch", "correct": false, "because": "Kühlung ist aufwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Quantenprozessoren unwichtig?', 3, '[{"text": "Kohärenzzeit", "correct": false, "because": "Entscheidend für Stabilität"}, {"text": "Fehlerkorrektur", "correct": false, "because": "Reduziert Ungenauigkeiten"}, {"text": "Monitorauflösung", "correct": true, "because": "Irrelevant für Berechnungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Nutzen Quantenprozessoren klassische Bits?', 2, '[{"text": "Nein", "correct": true, "because": "Sie nutzen Qubits"}, {"text": "Ja", "correct": false, "because": "Qubits statt Bits"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Quantenprozessoren für KI immer besser sind?', 3, '[{"text": "Nein", "correct": true, "because": "Nur für spezifische Probleme vorteilhaft"}, {"text": "Ja", "correct": false, "because": "Klassische GPUs oft effizienter"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Fehlerkorrektur bei Quantenprozessoren?', 4, '[{"text": "Stabilisiert Berechnungen", "correct": true, "because": "Kompensiert Störungen"}, {"text": "Erhöht Taktfrequenz", "correct": false, "because": "Irrelevant für Qubits"}, {"text": "Vereinfacht Programmierung", "correct": false, "because": "Erhöht Komplexität"}]');
